-- V2 master references only. No transaction data, no deletion, no duplicated branches.
ALTER TABLE branches ADD COLUMN city VARCHAR(100) NOT NULL DEFAULT '', ADD COLUMN province VARCHAR(100) NOT NULL DEFAULT '', ADD COLUMN phone VARCHAR(30) NOT NULL DEFAULT '', ADD COLUMN version INT UNSIGNED NOT NULL DEFAULT 1, ADD COLUMN created_at TIMESTAMP NULL DEFAULT NULL, ADD COLUMN updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
CREATE TABLE md_customers (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), branch_id INT UNSIGNED NOT NULL, UNIQUE(id,branch_id), INDEX(branch_id,active,name), CONSTRAINT fk_md_customers_branch_id FOREIGN KEY(branch_id) REFERENCES branches(id), customer_type VARCHAR(20) NOT NULL, address VARCHAR(500) NOT NULL DEFAULT '', phone VARCHAR(30) NOT NULL DEFAULT '', email VARCHAR(190) NOT NULL DEFAULT '', contact_name VARCHAR(150) NOT NULL DEFAULT '', CHECK(customer_type IN ('individual','company'))
) ENGINE=InnoDB;
CREATE TABLE md_parties (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), branch_id INT UNSIGNED NOT NULL, UNIQUE(id,branch_id), INDEX(branch_id,active,name), CONSTRAINT fk_md_parties_branch_id FOREIGN KEY(branch_id) REFERENCES branches(id), company VARCHAR(150) NOT NULL DEFAULT '', address VARCHAR(500) NOT NULL DEFAULT '', phone VARCHAR(30) NOT NULL DEFAULT '', party_role VARCHAR(12) NOT NULL, identity_hash CHAR(64) NOT NULL, UNIQUE(branch_id,identity_hash), CHECK(party_role IN ('sender','receiver','both'))
) ENGINE=InnoDB;
CREATE TABLE md_locations (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), branch_id INT UNSIGNED NOT NULL, UNIQUE(id,branch_id), INDEX(branch_id,active,name), CONSTRAINT fk_md_locations_branch_id FOREIGN KEY(branch_id) REFERENCES branches(id), city VARCHAR(100) NOT NULL DEFAULT '', province VARCHAR(100) NOT NULL DEFAULT ''
) ENGINE=InnoDB;
CREATE TABLE md_routes (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), branch_id INT UNSIGNED NOT NULL, UNIQUE(id,branch_id), INDEX(branch_id,active,name), CONSTRAINT fk_md_routes_branch_id FOREIGN KEY(branch_id) REFERENCES branches(id), destination_branch_id INT UNSIGNED NOT NULL, origin_location_id INT UNSIGNED NOT NULL, destination_location_id INT UNSIGNED NOT NULL,
 CONSTRAINT fk_md_route_destination_branch FOREIGN KEY(destination_branch_id) REFERENCES branches(id),
 CONSTRAINT fk_md_route_origin_location FOREIGN KEY(origin_location_id,branch_id) REFERENCES md_locations(id,branch_id),
 CONSTRAINT fk_md_route_destination_location FOREIGN KEY(destination_location_id,destination_branch_id) REFERENCES md_locations(id,branch_id),
 UNIQUE(branch_id,destination_branch_id,origin_location_id,destination_location_id)
) ENGINE=InnoDB;
CREATE TABLE md_assets (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), branch_id INT UNSIGNED NOT NULL, UNIQUE(id,branch_id), INDEX(branch_id,active,name), CONSTRAINT fk_md_assets_branch_id FOREIGN KEY(branch_id) REFERENCES branches(id), kind VARCHAR(12) NOT NULL, identity VARCHAR(100) NOT NULL, category VARCHAR(100) NOT NULL DEFAULT '', brand VARCHAR(100) NOT NULL DEFAULT '', model VARCHAR(100) NOT NULL DEFAULT '', capacity VARCHAR(100) NOT NULL DEFAULT '', condition_code VARCHAR(20) NULL,
 UNIQUE(kind,identity), CHECK(kind IN('truck','equipment')), CHECK(condition_code IS NULL OR condition_code IN('ready','maintenance'))
) ENGINE=InnoDB;
CREATE TABLE md_personnel (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NULL, branch_id INT UNSIGNED NOT NULL, kind VARCHAR(12) NOT NULL, phone VARCHAR(30) NOT NULL DEFAULT '', account_id INT UNSIGNED NULL UNIQUE,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT fk_md_personnel_branch_id FOREIGN KEY(branch_id) REFERENCES branches(id), CONSTRAINT fk_md_personnel_account_id FOREIGN KEY(account_id) REFERENCES users(id), UNIQUE(id,branch_id), INDEX(branch_id,kind,active), CHECK(active IN(0,1)), CHECK(kind IN('driver','operator')), CHECK((account_id IS NULL AND name IS NOT NULL) OR (account_id IS NOT NULL AND name IS NULL))
) ENGINE=InnoDB;
CREATE TABLE md_trucking_tariffs (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), branch_id INT UNSIGNED NOT NULL, UNIQUE(id,branch_id), INDEX(branch_id,active,name), CONSTRAINT fk_md_trucking_tariffs_branch_id FOREIGN KEY(branch_id) REFERENCES branches(id), service VARCHAR(12) NOT NULL, route_id INT UNSIGNED NULL, basis VARCHAR(150) NOT NULL, amount DECIMAL(12,2) NULL, valid_from DATE NULL, valid_until DATE NULL,
 CONSTRAINT fk_md_truck_tariff_route FOREIGN KEY(route_id,branch_id) REFERENCES md_routes(id,branch_id), CHECK(service IN('regular','charter','pickup')), CHECK(amount IS NULL OR amount>=0), CHECK((service='pickup' AND route_id IS NULL) OR (service IN('regular','charter') AND route_id IS NOT NULL)), CHECK(valid_from IS NULL OR valid_until IS NULL OR valid_from<=valid_until)
) ENGINE=InnoDB;
CREATE TABLE md_equipment_tariffs (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), branch_id INT UNSIGNED NOT NULL, UNIQUE(id,branch_id), INDEX(branch_id,active,name), CONSTRAINT fk_md_equipment_tariffs_branch_id FOREIGN KEY(branch_id) REFERENCES branches(id), asset_id INT UNSIGNED NOT NULL, period VARCHAR(12) NOT NULL, amount DECIMAL(12,2) NULL, valid_from DATE NULL, valid_until DATE NULL,
 CONSTRAINT fk_md_equipment_tariff_asset FOREIGN KEY(asset_id,branch_id) REFERENCES md_assets(id,branch_id), CHECK(period IN('hour','shift','month')), CHECK(amount IS NULL OR amount>=0), CHECK(valid_from IS NULL OR valid_until IS NULL OR valid_from<=valid_until)
) ENGINE=InnoDB;
CREATE TABLE md_categories (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), UNIQUE(name)
) ENGINE=InnoDB;
CREATE TABLE md_units (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), UNIQUE(name)
) ENGINE=InnoDB;
CREATE TABLE md_items (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), category_id INT UNSIGNED NOT NULL, unit_id INT UNSIGNED NOT NULL, CONSTRAINT fk_md_items_category_id FOREIGN KEY(category_id) REFERENCES md_categories(id), CONSTRAINT fk_md_items_unit_id FOREIGN KEY(unit_id) REFERENCES md_units(id), INDEX(category_id,unit_id,active,name)
) ENGINE=InnoDB;
CREATE TABLE md_suppliers (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1, version INT UNSIGNED NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CHECK(active IN(0,1)), branch_id INT UNSIGNED NOT NULL, UNIQUE(id,branch_id), INDEX(branch_id,active,name), CONSTRAINT fk_md_suppliers_branch_id FOREIGN KEY(branch_id) REFERENCES branches(id), address VARCHAR(500) NOT NULL DEFAULT '', phone VARCHAR(30) NOT NULL DEFAULT '', email VARCHAR(190) NOT NULL DEFAULT ''
) ENGINE=InnoDB;
